# GENERATED by search-core/sync.py — do not edit; edit search-core/searchcore.py and re-run sync.py
"""searchcore — the one forgiving-search implementation the whole fleet shares.

Every Nan site asks the same thing of a search box: the reader typed something
approximate, in one of two scripts, possibly in the wrong order, possibly run
together without spaces, and they should still land on the thing they meant.
Before this, each site answered that question its own way — Mot Dang with a
substring filter that grew a thesaurus and an edit-distance fallback, wichaa
with a vector index and a substring re-rank that did nothing at all for Thai.
Neither could read a compound Thai query, and neither knew what a reader was
actually asking for when they typed "somewhere cheap open now".

Four layers, applied in order, each one only widening what the one before it
could not reach:

  1. INTENT   the parts of a query that are not words to match but constraints
              to apply — open now, near me, cheap, wheelchair, no meat. Pulled
              out first, because they otherwise dilute every other layer: a
              reader typing "cheap dentist open now" was matching four words
              against names, and only one of them was the thing they wanted.
  2. SEGMENT  Thai is written without spaces, so a Thai query arrives as one
              long token that substring-matches nothing. Split on a dictionary
              of words the corpus actually contains. NOT character n-grams —
              boosting the syllable ภัย is what once made ยันต์กันภัย return
              ภัยยะราด.
  3. THESAURUS  synonymy, and only synonymy: coffee ↔ กาแฟ ↔ cafe. Spelling
              variants deliberately do NOT live here — layer 4 handles those,
              which is what keeps this table small enough to read and to trust.
  4. LOOSE    a phonetic key per script plus bounded edit distance on the key.
              There is no single right way to write ข้าวซอย in Latin letters and
              the signage in this city uses all of them; Thai misspellings are
              overwhelmingly homophone substitutions (ศ/ษ/ส, ณ/น, ไ/ใ), which a
              phonetic key catches by construction and edit distance catches
              only by luck.

The tiers are reported, never hidden. A reader who is shown a near-spelling
match without being told it was one has been quietly lied to about how well
the search understood them.

Stdlib only, and mirrored in searchcore.js — parity.py asserts the two agree.
"""

from __future__ import annotations

import json
import re
import unicodedata
from pathlib import Path

HERE = Path(__file__).resolve().parent
DATA = HERE / "data"

# ---------------------------------------------------------------------------
# Layer 0: normalization
# ---------------------------------------------------------------------------

_SARA_AM = "ำ"          # ำ  composed
_NIKHAHIT = "ํ"         # ํ  the ring, which OCR and some keyboards emit
_SARA_AA = "า"          # า
# ํ + า is the decomposed spelling of ำ, and tone marks sit between them when a
# syllable carries one. Both orders occur in real text, so both recompose.
_RE_NIKHAHIT_AA = re.compile(_NIKHAHIT + _SARA_AA)
_RE_TONE_NIKHAHIT_AA = re.compile("([่-๋])" + _NIKHAHIT + _SARA_AA)
_RE_ZERO_WIDTH = re.compile("[​-‏‪-‮﻿]")
_THAI_CHAR = re.compile("[฀-๿]")
# Underscore is a separator, not a letter: vocabulary keys arrive as coffee_shop
# and facility_type, and a reader types them as two words. Python's \w would keep
# it, so it is excluded by hand — and it has to match the JS side exactly, which
# is what parity.py is for.
_RE_NONWORD = re.compile(r"(?:[^\w฀-๿]|_)+", re.UNICODE)
_RE_YAMOK = re.compile(r"\s*ๆ")   # ๆ — "say the last word again"


def has_thai(s: str) -> bool:
    return bool(_THAI_CHAR.search(s or ""))


def _strip_latin_marks(s: str) -> str:
    """Drop accents from Latin letters; leave every Thai mark alone.

    "Café de Nimman" and "cafe" are the same word and the same shop, and the
    signage in this city writes it both ways — but they were two unrelated
    strings whose phonetic keys also differed, so the café ranked below places
    that merely share its road. Thai must be exempt: its vowels and tone marks
    ARE combining characters, and stripping them would delete the word.
    """
    if s.isascii():
        return s
    out = []
    for ch in unicodedata.normalize("NFD", s):
        if unicodedata.combining(ch):
            base = out[-1] if out else ""
            if base and base.isascii() and base.isalpha():
                continue
        out.append(ch)
    return unicodedata.normalize("NFC", "".join(out))


def norm(s: str) -> str:
    """Lowercase, recompose decomposed sara-am, expand ๆ, flatten punctuation.

    Runs on indexed text and on queries alike; anything done to one side and
    not the other is a bug that shows up as a query that cannot match its own
    document.
    """
    if not s:
        return ""
    s = unicodedata.normalize("NFC", s)
    s = _RE_ZERO_WIDTH.sub("", s)
    s = _RE_TONE_NIKHAHIT_AA.sub(r"\1" + _SARA_AM, s)
    s = _RE_NIKHAHIT_AA.sub(_SARA_AM, s)
    s = _strip_latin_marks(s)
    # ๆ repeats the preceding word, and a reader may type either form. Expand it
    # so ต่างๆ and ต่างต่าง are the same query.
    s = _RE_YAMOK.sub(lambda m: "", s) if False else s
    s = s.lower()
    s = _RE_NONWORD.sub(" ", s)
    return s.strip()


# --- the Thai phonetic key -------------------------------------------------
# Thai spelling carries history: half a dozen letters share one sound because
# they arrived from Sanskrit or Pali with their spelling intact. A reader who
# knows how a word SOUNDS but not which of the four /t/ letters it uses is not
# making a mistake so much as reporting a real ambiguity in the script. Fold
# each homophone class onto one representative and that whole category of miss
# disappears.
_TH_CONSONANT_CLASSES = {
    "ก": "ก",
    "ขฃคฅฆ": "ค",
    "ง": "ง",
    "จ": "จ",
    "ฉชฌ": "ช",
    "ซศษส": "ส",
    "ญย": "ย",
    "ฎด": "ด",
    "ฏต": "ต",
    "ฐฑฒถทธ": "ท",
    "ณน": "น",
    "บ": "บ",
    "ป": "ป",
    "ผพภ": "พ",
    "ฝฟ": "ฟ",
    "ม": "ม",
    "ร": "ร",
    "ลฬ": "ล",
    "ว": "ว",
    "หฮ": "ห",
    "อ": "อ",
    "ฤ": "ร",
    "ฦ": "ล",
}
_TH_MAP = {}
for _cls, _rep in _TH_CONSONANT_CLASSES.items():
    for _ch in _cls:
        _TH_MAP[_ch] = _rep

# Vowel confusions that are about length or shape rather than sound, plus the
# ไ/ใ pair — only twenty words in the language take ใ, so a reader guessing
# between them is guessing right almost by accident.
_TH_VOWEL_CLASSES = {
    "ี": "ิ", "ิ": "ิ",
    "ื": "ึ", "ึ": "ึ",
    "ู": "ุ", "ุ": "ุ",
    "ั": "ะ", "ะ": "ะ", "็": "ะ",
    "ใ": "ไ", "ไ": "ไ", "ัย": "ไ",
    "ๅ": "า", "า": "า",
}
# Tone marks, the silencer, and the vowel-shortener carry meaning but are the
# single most-dropped class of character in a typed query.
_TH_DROP = set("่้๊๋์ฺ๎็ๆ")

# --- the Latin key ---------------------------------------------------------
# Thai reaches Latin letters through at least six romanisation habits (RTGS,
# passport style, missionary spellings, and whatever the signwriter preferred),
# so the same shop is Rajavej, Rachawet, and Ratchavej on three different signs.
# Fold aspiration, voicing, and vowel digraphs down to a coarse phoneme set.
_LATIN_DIGRAPHS = [
    ("tch", "c"), ("dch", "c"),
    ("kh", "k"), ("ph", "p"), ("th", "t"), ("ch", "c"), ("gh", "k"),
    ("ng", "g"),
    ("ee", "i"), ("ii", "i"), ("ie", "i"),
    ("oo", "u"), ("uu", "u"), ("ou", "u"), ("ue", "u"), ("eu", "u"),
    ("ae", "e"), ("oe", "e"), ("ei", "i"),
    ("ai", "i"), ("ay", "i"), ("ay", "i"),
    ("aw", "o"), ("au", "o"), ("or", "o"), ("ao", "o"),
    ("ua", "u"), ("uo", "u"),
]
_LATIN_SINGLES = {
    "g": "k", "j": "c", "q": "k", "x": "s", "z": "s", "v": "w",
    "b": "p", "d": "t", "f": "p",
    # l and r are swapped constantly, in both directions, by speakers and by
    # romanisers. One representative for both.
    "l": "r",
    "y": "i", "h": "",
}


def loose(tok: str) -> str:
    """A phonetic key: two spellings of the same sound collapse to one string.

    Compared with edit distance rather than instead of it — the key removes the
    systematic differences between romanisations and Thai homophones, and the
    distance absorbs the ordinary slips left over.
    """
    tok = norm(tok)
    if not tok:
        return ""
    if has_thai(tok):
        out = []
        for ch in tok:
            if ch in _TH_DROP:
                continue
            ch = _TH_VOWEL_CLASSES.get(ch, ch)
            out.append(_TH_MAP.get(ch, ch))
        key = "".join(out)
    else:
        key = tok
        for a, b in _LATIN_DIGRAPHS:
            key = key.replace(a, b)
        key = "".join(_LATIN_SINGLES.get(c, c) for c in key)
    # Doubled anything, in either script, is noise once the classes are folded.
    out = []
    for ch in key:
        if not out or out[-1] != ch:
            out.append(ch)
    dedup = "".join(out)
    # A LATIN KEY THAT LOST MORE THAN HALF ITS LETTERS IS NOT A KEY. Folding
    # doubles is right for "coffee" (cofe); it also folded "zzzzqqq" to "sk",
    # and the nonsense a tester types to prove a miss matched SK House at the
    # loose tier with total confidence (mot-dang, 2026-09-10). Thai keys lose
    # marks by design and are left alone. Twin of the JS; parity.py checks.
    if not has_thai(tok) and len(dedup) * 2 < len(tok):
        return ""
    return dedup


def edits(a: str, b: str, cap: int) -> int:
    """Damerau-Levenshtein distance, abandoned once it passes `cap`.

    Transposition counts as one edit, not two: swapped adjacent letters are the
    commonest typo there is and the commonest disagreement between two
    romanisations of one Thai syllable.
    """
    la, lb = len(a), len(b)
    if abs(la - lb) > cap:
        return cap + 1
    if a == b:
        return 0
    prev2: list[int] = []
    prev = list(range(lb + 1))
    for i in range(1, la + 1):
        cur = [i] + [0] * lb
        lo, hi = max(1, i - cap), min(lb, i + cap)
        if lo > 1:
            cur[lo - 1] = cap + 1
        for j in range(lo, hi + 1):
            cost = 0 if a[i - 1] == b[j - 1] else 1
            v = min(prev[j] + 1, cur[j - 1] + 1, prev[j - 1] + cost)
            if (i > 1 and j > 1 and a[i - 1] == b[j - 2]
                    and a[i - 2] == b[j - 1]):
                v = min(v, prev2[j - 2] + 1)
            cur[j] = v
        if hi < lb:
            cur[hi + 1] = cap + 1
        if min(cur[lo:hi + 1] or [cap + 1]) > cap:
            return cap + 1
        prev2, prev = prev, cur
    return prev[lb]


def slack(tok: str) -> int:
    """How much misspelling a token has earned.

    A short word cannot be given a whole edit of slack without swallowing a
    different word entirely — one edit turns ยา into ยาย, and มา into หมา. Long
    words are safe, and are exactly where romanisations disagree most.

    Two edits start at EIGHT characters, not seven, and the extra character was
    bought with a real miss: `pharmacy` reduces to the key `parmaci` and `palace`
    to `parace`, which are two edits apart, so a search for a chemist returned
    thirteen hotels with Palace in the name. Two edits out of seven is a quarter
    of the word — enough slack to reach a genuinely different one. The ratio is
    what matters, not the count.
    """
    n = len(tok)
    if n <= 3:
        return 0
    if n <= 7:
        return 1
    return 2


# ---------------------------------------------------------------------------
# Layer 2: Thai segmentation
# ---------------------------------------------------------------------------

class Segmenter:
    """Dictionary longest-match segmentation for scripts written without spaces.

    The dictionary is the point. A general Thai wordlist segments grammar; a
    wordlist drawn from the corpus being searched segments the things a reader
    is actually looking for, so ร้านกาแฟนิมมาน comes apart into ร้าน + กาแฟ +
    นิมมาน and each piece is a word the index knows.

    Dynamic programming over the string, minimising the number of tokens and
    then preferring the longer split — the standard maximal-matching objective,
    which beats greedy left-to-right on exactly the compounds that matter
    (greedy takes a long wrong prefix and strands the rest).
    """

    def __init__(self, words):
        self.words = set()
        self.maxlen = 1
        for w in words:
            w = norm(w)
            if len(w) >= 2 and has_thai(w):
                self.words.add(w)
                self.maxlen = max(self.maxlen, len(w))
        self.maxlen = min(self.maxlen, 30)
        # Loose key -> the dictionary words that share it, for repairing a
        # misspelled chunk before it is ever split (see nearest()).
        self._by_loose: dict[str, list[str]] = {}
        for w in self.words:
            self._by_loose.setdefault(loose(w), []).append(w)
        self._loose_keys = sorted(self._by_loose)

    def nearest(self, chunk: str):
        """The dictionary word a misspelled chunk was probably meant to be.

        Segmentation and misspelling fight each other, and segmentation wins by
        default in the worst possible way: ราชเวส is not in any dictionary, but
        ราช and เวส both are, so the splitter shredded a hospital's name into two
        real words of three characters each — too short to earn any edit slack —
        and the query could no longer reach ราชเวช at all. A name misspelled by
        one letter must be recognised as a name BEFORE anything tries to take it
        apart.

        Only ever consulted for a chunk the dictionary does not already know, so
        a correctly spelled compound is never diverted through here.
        """
        chunk = norm(chunk)
        if not chunk or chunk in self.words:
            return None
        key = loose(chunk)
        if not key:
            return None
        hit = self._by_loose.get(key)
        if hit:
            return sorted(hit, key=lambda w: (abs(len(w) - len(chunk)), w))[0]
        cap = slack(key)
        if not cap:
            return None
        best, best_d = None, cap + 1
        for k in self._loose_keys:
            if abs(len(k) - len(key)) > cap:
                continue
            d = edits(key, k, cap)
            if d < best_d:
                best, best_d = k, d
                if d == 1:
                    break
        if best is None:
            return None
        return sorted(self._by_loose[best],
                      key=lambda w: (abs(len(w) - len(chunk)), w))[0]

    def split(self, s: str) -> list[str]:
        s = norm(s)
        if not s or not has_thai(s) or not self.words:
            return [s] if s else []
        n = len(s)
        # best[i] = (tokens, -length_of_last_known_word, path) reaching i
        INF = (10 ** 6, 0)
        best = [INF] * (n + 1)
        back = [(-1, False)] * (n + 1)
        best[0] = (0, 0)
        for i in range(n):
            if best[i] == INF:
                continue
            hit = False
            for L in range(min(self.maxlen, n - i), 1, -1):
                if s[i:i + L] in self.words:
                    hit = True
                    cand = (best[i][0] + 1, best[i][1] - L)
                    if cand < best[i + L]:
                        best[i + L] = cand
                        back[i + L] = (i, True)
            if not hit:
                # An unknown run costs the same as a word, so the segmenter
                # prefers to explain the string with known words but never
                # refuses a string it does not fully recognise.
                cand = (best[i][0] + 1, best[i][1])
                if cand < best[i + 1]:
                    best[i + 1] = cand
                    back[i + 1] = (i, False)
        if best[n] == INF:
            return [s]
        # Walk back, gluing consecutive unknown characters into one token.
        parts, j = [], n
        while j > 0:
            i, known = back[j]
            parts.append((s[i:j], known))
            j = i
        parts.reverse()
        out: list[str] = []
        for text, known in parts:
            if known or not out or out[-1][1]:
                out.append([text, known])
            else:
                out[-1][0] += text
        return [t for t, _ in out if t.strip()]


